SELECT s.s_name,s.s_address FROM tpch_supplier s JOIN tpch_nation n ON s.s_nationkey=n.n_nationkey JOIN (SELECT ps.ps_suppkey FROM tpch_partsupp ps JOIN tpch_part p ON p.p_partkey=ps.ps_partkey LEFT JOIN (SELECT l_partkey,l_suppkey,SUM(l_quantity) AS shipped_qty FROM tpch_lineitem WHERE l_shipdate>='1994-01-01' AND l_shipdate<'1995-01-01' GROUP BY l_partkey,l_suppkey) shipped ON shipped.l_partkey=ps.ps_partkey AND shipped.l_suppkey=ps.ps_suppkey WHERE p.p_name LIKE 'Part 1%' AND ps.ps_availqty>0.5*COALESCE(shipped.shipped_qty,0) GROUP BY ps.ps_suppkey) eligible ON eligible.ps_suppkey=s.s_suppkey WHERE n.n_name='CANADA' ORDER BY s.s_name;
